IF md5(pg_get_functiondef('private.pc_deliver_items(uuid,jsonb,text)'::regprocedure))<>'88e6b4ede79698ee36a0b568f1387f90' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pc_deliver_items(uuid,jsonb,text)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'SUPPLY_SOURCE_OR_ACL_DRIFT';END IF;
END $guard$;
DO $restore$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $restore$;
